/** A condition accepted by the conditional option helpers. */
export type OptionCondition = string | OptionDependency | OptionDependencies;

function conditionDependencies(
  condition: OptionCondition,
  required?: boolean,
): OptionDependencies {
  const dependencies = typeof condition === "string"
    ? { option: condition }
