    : { option: condition.option, ...(condition.value !== undefined && { value: condition.value }) };
  return { ...dependencies, ...(required !== undefined && { required }) };
}

function conditionalOptionArgs(
  condition: OptionCondition,
  flagSpec: OptionName | readonly OptionName[],
  valueParser: ValueParser<Mode, unknown> | undefined,
  required?: boolean,
): Parser<Mode, unknown, unknown> {
  const names = Array.isArray(flagSpec) ? flagSpec : [flagSpec];
  const options: OptionOptions = { dependsOn: conditionDependencies(condition, required) };
  return valueParser == null
    ? option(...names, options)
    : option(...names, valueParser, options);
}

/** Creates an option whose dependency must be satisfied. */
export function requiredWhen(
  condition: OptionCondition,
  flagSpec: OptionName | readonly OptionName[],
  valueParser?: ValueParser<Mode, unknown>,
): Parser<Mode, unknown, unknown> {
  return conditionalOptionArgs(condition, flagSpec, valueParser, true);
}

/** Creates an option hidden while its dependency is unsatisfied. */
export function optionalWhen(
  condition: OptionCondition,
  flagSpec: OptionName | readonly OptionName[],
  valueParser?: ValueParser<Mode, unknown>,
): Parser<Mode, unknown, unknown> {
  return conditionalOptionArgs(condition, flagSpec, valueParser, false);
}

/** Creates an option with conditional dependency metadata. */
export function conditionalOption(
  condition: OptionCondition,
  flagSpec: OptionName | readonly OptionName[],
  valueParser?: ValueParser<Mode, unknown>,
): Parser<Mode, unknown, unknown> {
  return conditionalOptionArgs(condition, flagSpec, valueParser);
